import {Image, StyleSheet, useWindowDimensions, View} from 'react-native';
import React, {useEffect} from 'react';
import BootSplash from 'react-native-bootsplash';
import {SplashScreenProps} from '@navigation/screens';
import Illustration from '@assets/svg/splashScreen/Illustration.svg';

// Same logo the native splash shows (generated by react-native-bootsplash at 192x128dp),
// centered the same way, so hiding the native splash doesn't make the logo jump.
const LOGO = require('../assets/bootsplash/logo.png');
const ILLUSTRATION_RATIO = 250 / 390;

const SplashScreen = ({navigation}: SplashScreenProps) => {
  const {width} = useWindowDimensions();

  useEffect(() => {
    const timer = setTimeout(() => {
      navigation.navigate('MainNavigator');
    }, 2000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <View style={styles.container}>
      <View style={styles.illustration}>
        <Illustration width={width} height={width * ILLUSTRATION_RATIO} />
      </View>
      <View style={styles.logoWrapper}>
        <Image
          source={LOGO}
          style={styles.logo}
          fadeDuration={0}
          onLoadEnd={() => BootSplash.hide({fade: true})}
        />
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  logoWrapper: {
    ...StyleSheet.absoluteFill,
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    width: 192,
    height: 128,
  },
  illustration: {
    position: 'absolute',
    left: 0,
    right: 0,
    bottom: 0,
  },
});

export default SplashScreen;
